<?php
require_once dirname(__DIR__) . '/auth.php';
require_once dirname(__DIR__) . '/app/auth-capabilities.php';
require_once dirname(__DIR__) . '/app/data-slot.php';
require_once dirname(__DIR__) . '/app/leden/service.php';
if(!$ingelogd){header('Location: ./');exit;}
if(!authHeeftCapability('tasks.manage')){http_response_code(403);echo'Geen toegang tot Taken.';exit;}
function tkEsc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function tkFlash(string $t,string $type='ok'):void{$_SESSION['taken_flash']=['tekst'=>$t,'type'=>$type];}
function tkRedirect():void{header('Location: taken.php');exit;}
function tkVind(array $data,string $id):?int{foreach((array)($data['taken']??[]) as $i=>$t)if(is_array($t)&&($t['id']??'')===$id)return$i;return null;}
function tkVergaderingSoort(array $vergaderingen,string $id):string{foreach((array)($vergaderingen['vergaderingen']??[]) as $v)if(is_array($v)&&($v['id']??'')===$id)return in_array(($v['soort']??''),['bestuur','leden'],true)?$v['soort']:'';return'';}
$flash=$_SESSION['taken_flash']??null;unset($_SESSION['taken_flash']);
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(!csrfOk()){tkFlash('Sessie verlopen.','fout');tkRedirect();}$slot=dataSlotOpen();try{$data=repoTakenLees();$actie=(string)($_POST['actie']??'');
  if($actie==='opslaan'){$id=trim((string)($_POST['id']??''));$idx=$id===''?null:tkVind($data,$id);$bestaand=$idx===null?null:$data['taken'][$idx];$vergId=trim((string)($_POST['vergadering_id']??''));$vergData=repoVergaderingenLees();$vergSoort=$vergId===''?'':tkVergaderingSoort($vergData,$vergId);$invoer=['omschrijving'=>$_POST['omschrijving']??'','toelichting'=>$_POST['toelichting']??'','status'=>$_POST['status']??'open','vergadering_soort'=>$vergSoort,'vergadering_id'=>$vergSoort===''?'':$vergId,'commissie_id'=>$_POST['commissie_id']??'','toegewezen_aan'=>$_POST['toegewezen_aan']??''];$t=taakNormaliseer($invoer,$bestaand);$ledenData=ledenServiceLees();if($t['toegewezen_aan']!==''&&!in_array($t['toegewezen_aan'],array_column($ledenData['leden'],'id'),true))$t['toegewezen_aan']='';if($t['commissie_id']!==''&&!array_key_exists($t['commissie_id'],ledenCommissies($ledenData)))$t['commissie_id']='';if($idx===null){$t['nummer']=taakVolgendNummer($data);$t['aangemaakt_door']=$huidigeGebruiker;$data['taken'][]=$t;}else$data['taken'][$idx]=$t;if(repoTakenSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'taak_opgeslagen',$t['id'].' · '.$t['omschrijving']);tkFlash('Taak opgeslagen.');}else tkFlash('Opslaan mislukt.','fout');}
  elseif($actie==='verwijderen'){$id=trim((string)($_POST['id']??''));$idx=tkVind($data,$id);if($idx===null)tkFlash('Taak niet gevonden.','fout');else{array_splice($data['taken'],$idx,1);if(repoTakenSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'taak_verwijderd',$id);tkFlash('Taak verwijderd.');}else tkFlash('Verwijderen mislukt.','fout');}}
 }finally{dataSlotDicht($slot);}tkRedirect();
}
$data=repoTakenLees();$lijst=takenGesorteerd($data);$editId=trim((string)($_GET['edit']??''));$edit=null;if($editId!=='')foreach((array)($data['taken']??[]) as $x)if(is_array($x)&&($x['id']??'')===$editId){$edit=$x;break;}$toon=($_GET['nieuw']??'')==='1'||$edit!==null;$t=$edit??['status'=>'open'];$ledenData=ledenServiceLees();$leden=array_values(array_filter($ledenData['leden'],static fn($l)=>is_array($l)&&empty($l['gearchiveerd_op'])));$commissies=ledenCommissies($ledenData);$verg=vergaderingenGesorteerd(repoVergaderingenLees());
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Taken</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{padding:14px 22px;background:#fff;border-bottom:1px solid #ddd8c0}.top a{color:#2d6260;font-weight:750;text-decoration:none}.wrap{max-width:1050px;margin:30px auto;padding:0 20px 70px}.card{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:20px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.veld label{display:block;font-weight:700;margin-bottom:5px}.veld input,.veld select,.veld textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d3ccb7;border-radius:8px;font:inherit}.veld textarea{min-height:110px}.btn{display:inline-block;border:1px solid #d3ccb7;background:#fff;color:#2d6260;border-radius:8px;padding:9px 12px;text-decoration:none;font:inherit;font-weight:750;cursor:pointer}.btn.primary{background:#3a7a77;color:#fff;border:0}.btn.danger{background:#fff0ed;color:#8b2e27}.actions{display:flex;gap:8px;flex-wrap:wrap}.item{border-top:1px solid #eee9db;padding:12px 0}.meta{font-size:13px;color:#68705f}.melding{padding:12px;border-radius:8px;background:#eaf6ee}.melding.fout{background:#fdeceb;color:#8b2e27}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style><link rel="stylesheet" href="ui-2026.css"></head><body><div class="top"><a href="./">← Beheer</a></div><main class="wrap"><h1>Taken</h1><a class="btn primary" href="?nieuw=1">+ Taak</a><?php if($flash):?><div class="melding <?=tkEsc($flash['type']??'')?>"><?=tkEsc($flash['tekst']??'')?></div><?php endif;?><?php if($toon):?><section class="card"><h2><?=$edit?'Taak bewerken':'Nieuwe taak'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=tkEsc($csrfToken)?>"><input type="hidden" name="actie" value="opslaan"><input type="hidden" name="id" value="<?=tkEsc($edit['id']??'')?>"><div class="grid"><div class="veld"><label>Omschrijving</label><input name="omschrijving" maxlength="200" value="<?=tkEsc($t['omschrijving']??'')?>"></div><div class="veld"><label>Status</label><select name="status"><?php foreach(takenStatussen() as $k=>$lab):?><option value="<?=tkEsc($k)?>" <?=($t['status']??'')===$k?'selected':''?>><?=tkEsc($lab)?></option><?php endforeach;?></select></div><div class="veld"><label>Toegewezen aan</label><select name="toegewezen_aan"><option value="">Niemand</option><?php foreach($leden as $l):?><option value="<?=tkEsc($l['id'])?>" <?=($t['toegewezen_aan']??'')===$l['id']?'selected':''?>><?=tkEsc(ledenVolledigeNaam($l))?></option><?php endforeach;?></select></div><div class="veld"><label>Commissie</label><select name="commissie_id"><option value="">Geen</option><?php foreach($commissies as $k=>$naam):?><option value="<?=tkEsc($k)?>" <?=($t['commissie_id']??'')===$k?'selected':''?>><?=tkEsc($naam)?></option><?php endforeach;?></select></div><div class="veld"><label>Vergadering</label><select name="vergadering_id"><option value="">Geen</option><?php foreach($verg as $v):?><option value="<?=tkEsc($v['id'])?>" <?=($t['vergadering_id']??'')===$v['id']?'selected':''?>><?=tkEsc(vergaderingWeergavenaam($v))?></option><?php endforeach;?></select></div></div><div class="veld"><label>Toelichting</label><textarea name="toelichting"><?=tkEsc($t['toelichting']??'')?></textarea></div><div class="actions"><button class="btn primary" type="submit">Opslaan</button><a class="btn" href="taken.php">Annuleren</a></div></form></section><?php endif;?><section class="card"><h2>Overzicht</h2><?php foreach($lijst as $item):?><div class="item"><strong><?=tkEsc(taakWeergavenaam($item))?></strong><br><span class="meta"><?=tkEsc(takenStatussen()[$item['status']??'']??'')?><?=($item['toegewezen_aan']??'')!==''?' · toegewezen':''?></span><div class="actions"><a class="btn" href="?edit=<?=tkEsc($item['id'])?>">Bewerken</a><form method="post" onsubmit="return confirm('Taak verwijderen?');"><input type="hidden" name="csrf" value="<?=tkEsc($csrfToken)?>"><input type="hidden" name="actie" value="verwijderen"><input type="hidden" name="id" value="<?=tkEsc($item['id'])?>"><button class="btn danger" type="submit">Verwijderen</button></form></div></div><?php endforeach;?></section></main></body></html>
